import{c as o,Q as l,j as r,m as e}from"./chunks/framework.DOi4mjdC.js";const g="/assets/%E6%8A%BD%E8%B1%A1%E7%A1%AC%E4%BB%B6%E6%9E%B6%E6%9E%84.HvLi5pTw.png",n=JSON.parse('{"title":"抽象硬件架构","description":"","frontmatter":{},"headers":[{"level":1,"title":"抽象硬件架构","slug":"抽象硬件架构"}],"relativePath":"guide/编程指南/编程模型/AI-Core-SIMD编程/抽象硬件架构.md","filePath":"guide/编程指南/编程模型/AI-Core-SIMD编程/抽象硬件架构.md"}'),u={name:"guide/编程指南/编程模型/AI-Core-SIMD编程/抽象硬件架构.md"};function a(q,t,p,s,d,c){return l(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="抽象硬件架构" tabindex="-1">抽象硬件架构 <a class="header-anchor" href="#抽象硬件架构" aria-label="Permalink to &quot;抽象硬件架构&quot;">​</a></h1><p>AI Core是AI处理器的计算核心，AI处理器内部有多个AI Core。本章节将介绍AI Core的并行计算架构抽象，该抽象架构屏蔽了不同硬件之间的差异。使用Ascend C进行编程时，基于抽象硬件架构，可以简化硬件细节，显著降低开发门槛。如需了解更详细的硬件架构信息或者原理，请参考<a href="./../../硬件实现/基本架构.html">硬件实现</a>。</p><p><strong>图 1</strong> 抽象硬件架构<br><img src="'+g+'" alt="" title="抽象硬件架构"></p><p>AI Core中包含<strong>计算单元、存储单元、搬运单元</strong>等核心组件。</p><ul><li><p>计算单元包括了三种基础计算资源：Cube计算单元、Vector计算单元和Scalar计算单元。</p></li><li><p>存储单元包括内部存储和外部存储：</p><ul><li>AI Core的内部存储，统称为Local Memory，对应的数据类型为LocalTensor。</li><li>AI Core能够访问的外部存储称之为Global Memory，对应的数据类型为GlobalTensor。</li></ul></li><li><p>DMA（Direct Memory Access）搬运单元：负责数据搬运，包括Global Memory和Local Memory之间的数据搬运，以及不同层级Local Memory之间的数据搬运。</p></li></ul><p>AI Core内部核心组件及组件功能详细说明如下表。</p><p><strong>表 1</strong> AI Core内部核心组件</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.371437143714372%&quot;&gt;&lt;p&gt;组件分类&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.082408240824083%&quot;&gt;&lt;p&gt;组件名称&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;61.546154615461546%&quot;&gt;&lt;p&gt;组件功能&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; rowspan=&quot;3&quot; valign=&quot;top&quot; width=&quot;14.371437143714372%&quot;&gt;&lt;p&gt;计算单元&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.082408240824083%&quot;&gt;&lt;p&gt;Scalar&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;61.546154615461546%&quot;&gt;&lt;p&gt;执行地址计算、循环控制等标量计算工作，并把向量计算、矩阵计算、数据搬运、同步指令发射给对应单元执行。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;Vector&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;负责执行向量运算。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;Cube&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;负责执行矩阵运算。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.371437143714372%&quot;&gt;&lt;p&gt;存储单元&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.082408240824083%&quot;&gt;&lt;p&gt;Local Memory&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;61.546154615461546%&quot;&gt;&lt;p&gt;&lt;span&gt;AI Core&lt;/span&gt;的内部存储。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.371437143714372%&quot;&gt;&lt;p&gt;搬运单元&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.082408240824083%&quot;&gt;&lt;p&gt;DMA（Direct Memory Access）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;61.546154615461546%&quot;&gt;&lt;p&gt;&lt;span&gt;负责数据搬运，包括Global Memory和Local Memory之间的数据搬运以及不同层级Local Memory之间的数据搬运。&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>开发者在理解硬件架构的抽象时，需要重点关注如下<strong>异步指令流、同步信号流</strong>、<strong>计算数据流</strong>三个过程：</p><ul><li>AI Core内部的异步并行计算过程：Scalar计算单元读取指令序列，并把向量计算、矩阵计算、数据搬运指令发射给对应单元的指令队列，向量计算单元、矩阵计算单元、数据搬运单元异步的并行执行接收到的指令。该过程可以参考<a href="#fig1095152043812">图1</a>中蓝色箭头所示的指令流。</li><li>不同的指令间有可能存在依赖关系，为了保证不同指令队列间的指令按照正确的逻辑关系执行，Scalar计算单元也会给对应单元下发同步指令。各单元之间的同步过程可以参考<a href="#fig1095152043812">图1</a>中的绿色箭头所示的同步信号流。</li><li>AI Core内部数据处理的基本过程：DMA搬入单元将数据从Global Memory搬运到Local Memory，Vector/Cube计算单元完成数据计算，并把计算结果写回Local Memory，DMA搬出单元把处理好的数据从Local Memory搬运回Global Memory。该过程可以参考<a href="#fig1095152043812">图1</a>中的红色箭头所示的数据流。</li></ul>',10)])])}const b=o(u,[["render",a]]);export{n as __pageData,b as default};
